<script lang="ts">
import {onDestroy} from 'svelte';import type {Language} from './i18n';import type {ObservedProcess} from './observations';import {prepareProcessStop,confirmProcessStop,discardProcessStop,type ProcessPlan,type ProcessAction} from './processResponse';
let {process,language,available,onChanged}:{process:ObservedProcess;language:Language;available:boolean;onChanged:()=>void}=$props();const it=$derived(language==='it');let plan=$state<ProcessPlan|null>(null),result=$state<ProcessAction|null>(null),busy=$state(false),confirmed=$state(false),error=$state(''),now=$state(Date.now());const expired=$derived(plan!==null&&now>=plan.expires_at*1000);const timer=setInterval(()=>now=Date.now(),1000);onDestroy(()=>{clearInterval(timer);if(plan)void discardProcessStop(plan.id).catch(()=>{});});
async function prepare(){if(!process.creation_filetime)return;busy=true;error='';result=null;confirmed=false;const old=plan;plan=null;try{if(old)await discardProcessStop(old.id);plan=await prepareProcessStop(process.pid,process.creation_filetime);}catch(e){error=String(e);}finally{busy=false;}}
async function execute(){if(!plan||!confirmed||expired)return;const submitted=plan;plan=null;confirmed=false;busy=true;error='';try{result=await confirmProcessStop(submitted.id);onChanged();}catch(e){error=String(e);}finally{busy=false;}}
async function cancel(){const old=plan;plan=null;confirmed=false;if(old)try{await discardProcessStop(old.id);}catch(e){error=String(e);}}
</script>
<section class="process-response"><button class="button secondary" disabled={busy||!available||!process.creation_filetime} onclick={prepare}>{it?'Prepara arresto di '+process.name:'Prepare to stop '+process.name}</button>{#if plan}<div class="stop-plan"><strong>{it?'Arrestare '+plan.target.name+'?':'Stop '+plan.target.name+'?'}</strong><p>{it?'La chiusura è forzata e può perdere dati non salvati. Agisce solo su questa istanza; non blocca un riavvio o i processi figli. Windows, piko, processi critici e altre sessioni sono esclusi.':'Forced termination can lose unsaved data. It affects only this instance; restart and child processes are not blocked. Windows, piko, critical processes and other sessions are excluded.'}</p><code>{plan.target.executable} · PID {plan.target.pid}</code>{#if expired}<p>{it?'Anteprima scaduta.':'Preview expired.'}</p>{/if}<label><input type="checkbox" bind:checked={confirmed} disabled={busy||expired}/>{it?'Confermo l’arresto forzato di questa istanza.':'I confirm forced termination of this instance.'}</label><div><button class="button primary contain-action" disabled={busy||expired||!confirmed} onclick={execute}>{it?'Arresta processo':'Stop process'}</button><button class="button secondary" disabled={busy} onclick={cancel}>{it?'Annulla':'Cancel'}</button></div></div>{/if}{#if result}<p role="status">{result.status==='terminated'?(it?'Windows ha confermato la fine di '+result.target.name+'.':'Windows confirmed that '+result.target.name+' exited.'):(it?'Esito da verificare: ':'Outcome requires review: ')+result.detail}</p>{/if}{#if error}<p role="alert">{error}</p>{/if}</section>
<style>.process-response{margin:18px 0}.stop-plan{margin:12px 0;padding:18px;border:1px solid var(--warning-border);border-radius:12px;background:var(--warning-surface)}p,label{font-size:.76rem;line-height:1.7}code{font-size:.72rem;overflow-wrap:anywhere;display:block}label{display:flex;gap:8px;margin:14px 0}.stop-plan>div{display:flex;gap:8px;flex-wrap:wrap}</style>
